    let app = XCUIApplication(bundleIdentifier: "im.vector.app")

    func testOpenBobConversation() {
        app.launch()
        sleep(1)

        // Try to tap Cancel button on the dialog
        let cancelButton = app.buttons["Cancel"]
        if cancelButton.exists {
            cancelButton.tap()
            sleep(1)
        }

        // Tap on Bob's conversation
        let bobCell = app.cells.containing(.staticText, identifier: "Bob").element
        if bobCell.exists {
            bobCell.tap()
            sleep(1)
        }

        // Type the message
        let textField = app.textFields.firstMatch
        if textField.exists {
            textField.typeText("hi bob")
            sleep(1)
        }

        // Send the message (usually Enter or Send button)
